def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (everything after '+')
        if '+' in v:
            v_no_build = v.split('+')[0]
        else:
            v_no_build = v

        # Split into core version and pre-release (everything after first '-')
        if '-' in v_no_build:
            core, prerelease = v_no_build.split('-', 1)
        else:
            core = v_no_build
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            for identifier in prerelease.split('.'):
                # Check if all digits
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))

        return (major, minor, patch, prerelease_identifiers)

    def compare_key(v):
        major, minor, patch, prerelease_identifiers = parse_version(v)

        # Version without pre-release sorts after version with pre-release
        # So we use: (major, minor, patch, has_no_prerelease, prerelease_identifiers)
        # where has_no_prerelease = False if prerelease exists, True otherwise
        has_no_prerelease = len(prerelease_identifiers) == 0

        return (major, minor, patch, has_no_prerelease, prerelease_identifiers)

    # Sort using a stable sort to maintain input order for equal precedence
    return sorted(versions, key=compare_key)

